import * as THREE from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {ModelRenderer} from './model-renderer.js';
import {createPlayer,playerParts,partHeadSkin} from './player-model.js';
import {unbakedHeads,bakeHeadSkin} from './head-textures.js';
import {clone} from './physics.js';

import {lookupPlayer,skinCanvas} from './player-skins.js';
export function initPlayerImport({assets,getProject,getSelection,getSelectedGroup,applyProject,toast}){
 const dialog=document.createElement('dialog');dialog.id='skinDialog';dialog.className='skin-dialog';
 dialog.innerHTML='<div class="dialog-heading"><h2>플레이어 래그돌</h2><button class="icon-button" data-close="skinDialog" aria-label="닫기">×</button></div><div class="skin-workspace"><div class="skin-source"><label class="field-label" for="skinNickname">닉네임</label><div class="skin-lookup"><input id="skinNickname" placeholder="Minecraft 닉네임" maxlength="16" spellcheck="false"><button id="skinLookup">불러오기</button></div><div class="skin-source-divider">또는</div><label class="skin-upload">스킨 파일 불러오기<input id="skinPNG" type="file" accept="image/png" hidden></label><span id="skinFileName"></span><label class="field-label" for="skinVariant">스킨 형태</label><select id="skinVariant"><option value="classic">기본 · 4px</option><option value="slim">슬림 · 3px</option></select><button id="skinDefault" class="quiet">기본 스티브</button></div><div class="skin-preview"><canvas id="skinPreview" aria-label="래그돌 스킨 미리보기"></canvas></div></div><details class="skin-bake"><summary>데이터팩 텍스처 변환</summary><p>플레이어 부위를 Minecraft 커스텀 머리 텍스처로 변환합니다.</p><div class="skin-bake-controls"><input id="skinAPIKey" type="password" autocomplete="off" placeholder="MineSkin API 키"><a href="https://account.mineskin.org/keys" target="_blank" rel="noopener noreferrer">API 키</a><button id="skinBakeAll">장면 텍스처 변환</button></div><p class="compact-note">변환할 PNG를 MineSkin에 보냅니다. API 키는 저장하지 않습니다.</p></details><div class="dialog-footer"><span id="skinStatus" role="status"></span><button id="skinApply" class="primary">래그돌 추가</button></div>';
 document.body.append(dialog);const $=id=>dialog.querySelector('#'+id);let skin=null,playerName='Steve',generation=0,controller=null,bakeController=null,renderer,scene,camera,controls,models,roots=[];
 const status=text=>$('skinStatus').textContent=text;
 function disposeRoots(items){if(!models)return;for(const root of items){scene.remove(root);models.disposeRoot(root);}}
 function loop(){if(!dialog.open)return;controls?.update();renderer?.render(scene,camera);requestAnimationFrame(loop);}
 async function preview(){const current=++generation;if(!skin)return;
  if(!renderer){renderer=new THREE.WebGLRenderer({canvas:$('skinPreview'),alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(300,320,false);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(35,300/320,.01,100);scene.add(new THREE.HemisphereLight('#ffffff','#667080',2.4));const light=new THREE.DirectionalLight('#ffffff',2);light.position.set(3,5,4);scene.add(light);controls=new OrbitControls(camera,$('skinPreview'));controls.enableDamping=true;models=new ModelRenderer();camera.position.set(-2.1,1.1,-3.8);controls.target.set(0,0,0);controls.update();}
  const next=[];try{for(const part of playerParts($('skinVariant').value)){const model=await assets().paintedHead('minecraft:player_head',partHeadSkin(skin,part));if(current!==generation){disposeRoots(next);return;}const base=model.colliders[0],size=part.dims.map((v,i)=>v/16/base.s[i]),center=part.center.map((v,i)=>v/16-(i===1?1:0)),root=new THREE.Group();root.position.fromArray(center.map((v,i)=>v-base.c[i]*size[i]));root.scale.fromArray(size);next.push(root);await models.fill(root,{type:'item',block:'minecraft:player_head',visualParts:model.parts},assets(),{});if(current!==generation){disposeRoots(next);return;}}
  disposeRoots(roots);roots=next;for(const root of roots)scene.add(root);await models.ready();}catch(e){disposeRoots(next);throw e;}
 }
 async function setSkin(source,name,variant='classic'){const next=await skinCanvas(source);skin=next;playerName=name;$('skinVariant').value=variant;$('skinFileName').textContent=name;await preview();status(name+' · 래그돌을 추가할 수 있어요.');}
 const run=fn=>async()=>{try{await fn();}catch(e){if(e.name!=='AbortError'){status(e.message);toast(e.message);}}};
 const busy=value=>{for(const id of ['skinLookup','skinDefault','skinApply','skinVariant'])$(id).disabled=value;dialog.classList.toggle('busy',value);};
 $('skinLookup').onclick=run(async()=>{controller?.abort();controller=new AbortController();busy(true);status('스킨 불러오는 중');try{const result=await lookupPlayer($('skinNickname').value,{signal:controller.signal});const r=await fetch(result.url,{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(20000)])});if(!r.ok)throw new Error('플레이어 스킨을 불러오지 못했습니다.');const blob=await r.blob(),url=URL.createObjectURL(blob);try{if(controller.signal.aborted)return;await setSkin(url,result.name,result.variant);}finally{URL.revokeObjectURL(url);}}finally{busy(false);}});
 $('skinNickname').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('skinLookup').click();}};
 $('skinPNG').onchange=run(async()=>{const file=$('skinPNG').files[0];if(!file)return;if(file.size>1048576)throw new Error('스킨 PNG는 1 MB까지 지원합니다.');busy(true);const url=URL.createObjectURL(file);try{await setSkin(url,file.name.replace(/\.png$/i,''),$('skinVariant').value);}finally{URL.revokeObjectURL(url);$('skinPNG').value='';busy(false);}});
 $('skinVariant').onchange=run(preview);
 $('skinDefault').onclick=run(async()=>setSkin((await assets().texture('minecraft:entity/player/wide/steve')).url,'Steve'));
 $('skinApply').onclick=run(async()=>{if(!skin)throw new Error('스킨을 먼저 불러오세요.');busy(true);try{const p=clone(getProject()),id=await createPlayer(p,skin,{assets:assets(),variant:$('skinVariant').value,ragdoll:true,name:playerName});if(await applyProject(p,null,id)){dialog.close();toast('플레이어 래그돌을 추가했어요.');}}finally{busy(false);}});
 $('skinBakeAll').onclick=run(async()=>{const pending=unbakedHeads(getProject());if(!pending.length)return status('변환할 텍스처가 없습니다.');if(!$('skinAPIKey').value.trim())throw new Error('MineSkin API 키를 입력하세요.');bakeController=new AbortController();$('skinBakeAll').disabled=true;busy(true);const completed=new Map();try{const unique=[...new Set(pending.map(o=>o.headSkin))];for(let i=0;i<unique.length;i++){if(!unique[i])throw new Error('변환할 PNG가 없습니다.');const result=await bakeHeadSkin(unique[i],$('skinAPIKey').value,{signal:bakeController.signal,onStatus:s=>status((i+1)+'/'+unique.length+' · '+s)});completed.set(unique[i],result.value);if(result.delay&&i<unique.length-1)await new Promise(r=>setTimeout(r,result.delay));}status('텍스처 변환 완료');}finally{const p=clone(getProject());for(const o of p.objects){const value=completed.get(o.headSkin);if(value){o.headTexture=value;o.headNeedsBake=false;}}if(completed.size)await applyProject(p,getSelection(),getSelectedGroup());$('skinBakeAll').disabled=false;busy(false);bakeController=null;}});
 dialog.addEventListener('close',()=>{controller?.abort();bakeController?.abort();generation++;});
 return {async open({bake=false}={}){dialog.querySelector('details').open=bake;dialog.showModal();loop();if(!skin){busy(true);try{await setSkin((await assets().texture('minecraft:entity/player/wide/steve')).url,'Steve');}catch(e){status(e.message);}finally{busy(false);}}},close:()=>dialog.close()};
}
